use crate::model::{Plan, Study};
fn esc(s:&str)->String{let mut o=String::new();for c in s.chars(){match c{'"'=>o.push_str("\\\""),'\\'=>o.push_str("\\\\"),'\n'=>o.push_str("\\n"),'\r'=>o.push_str("\\r"),'\t'=>o.push_str("\\t"),c if c<' '=>o.push_str(&format!("\\u{:04x}",c as u32)),c=>o.push(c)}}o}
fn sha256(data:&[u8])->String{const K:[u32;64]=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];let mut m=data.to_vec();let bit=(m.len() as u64)*8;m.push(0x80);while m.len()%64!=56{m.push(0);}m.extend_from_slice(&bit.to_be_bytes());let mut h=[0x6a09e667u32,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];for ch in m.chunks(64){let mut w=[0u32;64];for i in 0..16{w[i]=u32::from_be_bytes(ch[i*4..i*4+4].try_into().unwrap());}for i in 16..64{let s0=w[i-15].rotate_right(7)^w[i-15].rotate_right(18)^(w[i-15]>>3);let s1=w[i-2].rotate_right(17)^w[i-2].rotate_right(19)^(w[i-2]>>10);w[i]=w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);}let(mut a,mut b,mut c,mut d,mut e,mut f,mut g,mut hh)=(h[0],h[1],h[2],h[3],h[4],h[5],h[6],h[7]);for i in 0..64{let s1=e.rotate_right(6)^e.rotate_right(11)^e.rotate_right(25);let chh=(e&f)^(!e&g);let t1=hh.wrapping_add(s1).wrapping_add(chh).wrapping_add(K[i]).wrapping_add(w[i]);let s0=a.rotate_right(2)^a.rotate_right(13)^a.rotate_right(22);let maj=(a&b)^(a&c)^(b&c);let t2=s0.wrapping_add(maj);hh=g;g=f;f=e;e=d.wrapping_add(t1);d=c;c=b;b=a;a=t1.wrapping_add(t2);}for(i,v)in[a,b,c,d,e,f,g,hh].iter().enumerate(){h[i]=h[i].wrapping_add(*v);}}h.iter().map(|x|format!("{:08x}",x)).collect()}
fn preimage(study:&Study,plan:Option<&Plan>)->String{match plan{None=>"{\"status\":\"infeasible\",\"optimal_count\":0}".to_string(),Some(p)=>{let mut s=format!("{{\"status\":\"ok\",\"phase\":\"{}\",\"calibration\":[{{\"scan\":\"{}\",\"scale\":{},\"shift\":{}}},{{\"scan\":\"{}\",\"scale\":{},\"shift\":{}}}],\"objective\":{{\"indexed_weight\":{},\"consensus\":{},\"residual\":{},\"missing\":{},\"orphans\":{},\"motion\":{}}},\"optimal_count\":{},\"scans\":[",p.phase,esc(&study.scans[0].name),p.a[0],p.z[0],esc(&study.scans[1].name),p.a[1],p.z[1],p.objective.indexed_weight,p.objective.consensus,p.objective.residual,p.objective.missing,p.objective.orphans,p.objective.motion,p.optimal_count);for si in 0..2{if si>0{s.push(',');}let sp=&p.scans[si];let scan=&study.scans[si];s.push_str(&format!("{{\"name\":\"{}\",\"assignments\":[",esc(&scan.name)));let mut first=true;for(i,n)in sp.assign.iter().enumerate(){if *n==0{continue;}if !first{s.push(',');}first=false;let sh=p.shells.iter().find(|x|x.n==*n).unwrap();let pred=p.a[si]*(*n as i64)+p.z[si];let res=(scan.peaks[i].q-pred).abs();s.push_str(&format!("{{\"peak\":\"{}\",\"shell\":{},\"hkl\":[{},{},{}],\"predicted\":{},\"residual\":{}}}",esc(&scan.peaks[i].id),n,sh.h,sh.k,sh.l,pred,res));}s.push_str("],\"impurities\":[");let mut f=true;for(i,n)in sp.assign.iter().enumerate(){if *n!=0{continue;}if !f{s.push(',');}f=false;s.push_str(&format!("\"{}\"",esc(&scan.peaks[i].id)));}s.push_str("],\"missing_shells\":[");for(i,n)in sp.missing.iter().enumerate(){if i>0{s.push(',');}s.push_str(&n.to_string());}s.push_str("]}");}s.push_str("]}");s}}}
pub fn render(study:&Study,plan:Option<&Plan>)->String{let pre=preimage(study,plan);let d=sha256(pre.as_bytes());let mut out=pre;out.pop();out.push_str(&format!(",\"digest\":\"{}\"}}\n",d));out}
